function storageBanner(){var b=el('storageBanner');if(!b)return;if(storage){b.hidden=true;return}b.hidden=false;b.innerHTML='<strong>الحفظ الدائم غير متاح.</strong> اللعب يعمل بصورة طبيعية، ويمكن تصدير النتيجة يدويًا من السجل.'}
function loadUser(){state.userName=storeGet(NAME_KEY,'نور')||'نور';state.userGender=storeGet(GENDER_KEY,'girl')==='boy'?'boy':'girl';updateUserButton()}
function saveUser(name,gender){name=String(name||'').replace(/^\s+|\s+$/g,'');if(!name)name='نور';state.userName=name;state.userGender=gender==='boy'?'boy':'girl';storeSet(NAME_KEY,name);storeSet(GENDER_KEY,state.userGender);updateUserButton();toast('تم حفظ الاسم');setAudioStatus('جاهز للتشجيع باسم '+name);if(window.Audio360&&Audio360.reload)Audio360.reload()}
function updateUserButton(){var b=el('profileBtn');if(b)b.innerHTML=uiIcon('user',state.userName)}
function setAudioStatus(t){var e=el('audioStatus');if(e)e.innerHTML=esc(t||'')}
window.PenKidsCore={getUserName:function(){return state.userName||'نور'},setStatus:function(t){setAudioStatus(t)}};
function speakCheer(){var name=state.userName||'نور',phrases=['أحسنت يا '+name,'رائع يا '+name,'ممتاز يا '+name,'عمل جميل يا '+name,'أبدعت يا '+name];var text=phrases[Math.floor(Math.random()*phrases.length)];setAudioStatus(text);try{if(window.Audio360&&Audio360.speak){Audio360.speak(text,true);return}}catch(e){}try{if(window.speechSynthesis&&window.SpeechSynthesisUtterance){speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(text);u.lang='ar-SA';u.rate=.86;speechSynthesis.speak(u)}}catch(e){}}
function testAudio(){var text='مرحبا يا '+(state.userName||'نور')+'، هيا نلعب';setAudioStatus('اختبار الصوت…');try{if(window.Audio360&&Audio360.speak){Audio360.speak(text,true);return}}catch(e){}speakCheer()}
function levelLabel(n){return['','المستوى الأول · أرى وألمس','المستوى الثاني · أوصل وأكرر','المستوى الثالث · أرتب وأحل','المستوى الرابع · أفكر وأبتكر'][n]}
function levelAge(n){return['','تقريبًا 1–2 سنة','تقريبًا 2–3.5 سنة','تقريبًا 3.5–5 سنوات','امتداد تقريبي 5–7 سنوات'][n]}
function levelHelp(n){return['','اختيار ولمس ومطابقة واضحة جدًا، مع مرافق بالغ ومساحة لعب حقيقية.','توصيل بسيط وأنماط وذاكرة قصيرة بصور مألوفة.','تسلسل وفرز وبازل ونقاط ومسارات مع تقليل المساعدة تدريجيًا.','قرائن وقاعدتان وابتكار لغز؛ امتداد اختياري لمن أصبح مستعدًا، وليس اختبار عمر.'][n]}
function currentGames(){return GAMES.filter(function(g){return g.level===state.level})}
function findGame(id){for(var i=0;i<GAMES.length;i++)if(GAMES[i].id===id)return GAMES[i];return null}

/* v8 navigation, stable visual assets, and legacy-browser fallbacks */
var UI_ICON_BASE='../../../assets/ui-icons/';
var OBJECT_ASSET_BASE='../say-and-name/assets/objects/';
var WORD_IMAGE_BASE='../say-and-name/assets/word-images/';
function uiIcon(name,label){return'<img class="ui-icon" src="'+UI_ICON_BASE+name+'.svg" alt="" aria-hidden="true"><span>'+esc(label||'')+'</span>'}
function typeIconName(t){var m={choice:'choice',pattern:'pattern',match:'match',sort:'sort',memory:'memory',order:'order',puzzle:'puzzle',dots:'dots',path:'path',draw:'draw',create:'draw',mark:'check'};return m[t]||'games'}
function gameListFor(g){return GAMES.filter(function(x){return x.level===g.level})}
function gameNeighbor(g,delta){var list=gameListFor(g),i=0;for(i=0;i<list.length;i++)if(list[i].id===g.id)break;if(!list.length)return g;i=(i+delta+list.length)%list.length;return list[i]}
