function gamePosition(g){var list=gameListFor(g),i=0;for(i=0;i<list.length;i++)if(list[i].id===g.id)break;return (i+1)+' / '+list.length}
var VISUAL_ASSETS={'🍎':['apple.svg','تفاحة'],'⚽':['ball.svg','كرة'],'🍌':['banana.svg','موز'],'📘':['book.svg','كتاب'],'🚗':['car.svg','سيارة'],'🐱':['cat.svg','قطة'],'🪑':['chair.svg','كرسي'],'🥤':['cup.svg','كوب'],'👟':['shoe.svg','حذاء'],'🥄':['spoon.svg','ملعقة'],'🪥':['toothbrush.svg','فرشاة أسنان'],'💧':['water.svg','ماء']};
