function visualMarkup(v){v=String(v==null?'':v);if(VISUAL_ASSETS[v])return'<span class="stable-visual"><img src="'+OBJECT_ASSET_BASE+VISUAL_ASSETS[v][0]+'" alt="'+esc(VISUAL_ASSETS[v][1])+'"><small>'+esc(VISUAL_ASSETS[v][1])+'</small></span>';var animals={'🐘':'corrected-elephant-v24.jpg','🦁':'corrected-lion-v24.jpg','🦈':'corrected-shark-v24.jpg','🐢':'corrected-turtle-v24.jpg','🦭':'corrected-walrus-v24.jpg'};if(animals[v])return'<span class="stable-visual photo"><img src="'+WORD_IMAGE_BASE+animals[v]+'" alt="'+esc(VISUAL_NAMES[v]||'صورة')+'"><small>'+esc(VISUAL_NAMES[v]||'صورة')+'</small></span>';var colors={'🔴':'red','🟥':'red','🔵':'blue','🟦':'blue','🟢':'green','🟩':'green','🟡':'yellow','🟨':'yellow','🟣':'purple','🟪':'purple','⚫':'black','⚪':'white'};if(colors[v])return'<span class="stable-visual"><i class="color-swatch '+colors[v]+'"></i><small>'+esc(v)+'</small></span>';if(VISUAL_NAMES[v])return'<span class="stable-visual fallback"><b>'+esc(v)+'</b><small>'+esc(VISUAL_NAMES[v])+'</small></span>';return'<span class="stable-visual fallback"><b>'+esc(v)+'</b></span>'}
function enhanceLegacyVisuals(box){if(!box)return;var sels=['.choice-grid button','.match-btn','.sort-item','.memory-card','.order-grid button','.puzzle-piece','.puzzle-slot','.creator-source button','.mark-value'];for(var s=0;s<sels.length;s++){var nodes=arr(box.querySelectorAll(sels[s]));for(var i=0;i<nodes.length;i++){var n=nodes[i];if(n.getAttribute('data-visualized')==='1')continue;var value=n.getAttribute('data-value')||n.textContent||'';value=String(value).replace(/^\s+|\s+$/g,'');if(!value)continue;if(VISUAL_ASSETS[value]||VISUAL_NAMES[value]||/^[🔴🟥🔵🟦🟢🟩🟡🟨🟣🟪⚫⚪]$/.test(value)){n.innerHTML=visualMarkup(value);n.setAttribute('data-visualized','1')}}}}

function targetFor(g){if(g.type==='mark'){var mo=g.markOptions||[],mc=0;for(var mi=0;mi<mo.length;mi++)if(mo[mi][1])mc++;return mc||1}if(g.type==='match')return(g.pairs||[]).length||1;if(g.type==='sort')return(g.items||[]).length||1;if(g.type==='memory')return(g.cards||[]).length||1;if(g.type==='dots')return Math.max(1,((g.points||[]).length-1));if(g.type==='path')return Math.max(1,((g.path||[]).length-1));if(g.type==='puzzle')return(g.symbols||[]).length||4;return 1}
function newSession(g,mode){var target=targetFor(g);state.round={attempts:0,correct:0,wrong:0,completed:0,target:target,finished:false,hints:0};state.session={session_id:nowId(),task_id:g.id,attempts:0,artifact:{game_id:g.id,title:g.title,selected_mode:mode||null,result:null},reflection:'',assistance_level:'مع المرافق',created_at:new Date().toISOString()}}
function scoreAttempt(ok,unit){if(!state.round)return;state.round.attempts++;state.session.attempts=state.round.attempts;if(ok){state.round.correct++;if(unit!==false)state.round.completed=clamp(state.round.completed+1,0,state.round.target);if(state.round.completed>=state.round.target&&!state.round.finished){state.round.finished=true;setTimeout(function(){speakCheer()},80)}}else state.round.wrong++;updateScoreHud()}
function scoreManualComplete(){if(!state.round||state.round.finished)return;state.round.attempts++;state.round.correct++;state.round.completed=state.round.target;state.round.finished=true;state.session.attempts=state.round.attempts;updateScoreHud();speakCheer()}
function accuracy(){if(!state.round||!state.round.attempts)return 0;return Math.round(state.round.correct/state.round.attempts*100)}
function completionPct(){if(!state.round||!state.round.target)return 0;return Math.round(state.round.completed/state.round.target*100)}
function resultText(){if(!state.round)return'لم تبدأ الجولة بعد';if(state.round.completed>=state.round.target){if(accuracy()>=80)return'اكتملت فكرة الجولة بنجاح';return'اكتملت الفكرة بعد عدة محاولات'}if(state.round.attempts)return'محاولة جزئية — يمكن إنهاؤها الآن أو تكرارها';return'جاهزون للبدء'}
function updateScoreHud(){var r=state.round;if(!r)return;var a=el('scoreAttempts'),c=el('scoreCorrect'),p=el('scoreProgress'),bar=el('scoreBar'),label=el('roundState');if(a)a.textContent=r.attempts;if(c)c.textContent=r.correct;if(p)p.textContent=completionPct()+'%';if(bar)bar.style.width=completionPct()+'%';if(label)label.textContent=resultText();var finish=el('finishScreen');if(finish)finish.innerHTML=uiIcon('finish',r.finished?'عرض نتيجة الجولة':'إنهاء وعرض النتيجة')}
function svgText(x,y,t,size,fill){return'<text x="'+x+'" y="'+y+'" text-anchor="middle" dominant-baseline="middle" font-size="'+size+'" fill="'+(fill||'#17302f')+'" font-family="Arial, sans-serif">'+esc(t)+'</text>'}
function tracePoints(g){return(g.type==='dots'?g.points:g.path)||[]}
function tracePoint(pt,w,h){var px=w*.08,py=h*.10;return{x:px+(Number(pt[0])||0)*(w-px*2)/100,y:py+(100-(Number(pt[1])||0))*(h-py*2)/100}}
function traceProgressCount(points,frameIndex){if(points.length<2)return 0;return Math.min(points.length-1,Math.max(1,Math.ceil((frameIndex+1)*(points.length-1)/5)))}
function traceSvg(g,i){var pts=tracePoints(g),w=640,h=360,bg=['#e8faf7','#fff4cb','#eef4ff','#f7edff','#eaf8e5'][i%5],body='<rect width="640" height="360" rx="30" fill="'+bg+'"/><rect x="20" y="20" width="600" height="320" rx="22" fill="#fff" stroke="#dceae8" stroke-width="3"/>',done=traceProgressCount(pts,i),p,q,k;for(k=0;k<pts.length-1;k++){p=tracePoint(pts[k],w,h);q=tracePoint(pts[k+1],w,h);body+='<line x1="'+p.x+'" y1="'+p.y+'" x2="'+q.x+'" y2="'+q.y+'" stroke="#c6d7d5" stroke-width="8" stroke-linecap="round" stroke-dasharray="12 12"/>';if(k<done)body+='<line x1="'+p.x+'" y1="'+p.y+'" x2="'+q.x+'" y2="'+q.y+'" stroke="#0f8f8a" stroke-width="9" stroke-linecap="round"/>'}for(k=0;k<pts.length;k++){p=tracePoint(pts[k],w,h);var fill=k===0?'#ef4444':(k===pts.length-1?'#1c9f69':'#0f8f8a'),r=k===0||k===pts.length-1?16:13;body+='<circle cx="'+p.x+'" cy="'+p.y+'" r="'+r+'" fill="'+fill+'" stroke="#fff" stroke-width="4"/>';body+=svgText(p.x,p.y,String(k+1),k===0||k===pts.length-1?16:14,'#fff')}if(pts.length){p=tracePoint(pts[0],w,h);q=tracePoint(pts[pts.length-1],w,h);var sx=Math.max(70,Math.min(570,p.x)),sy=Math.max(39,p.y-33),ex=Math.max(70,Math.min(570,q.x)),ey=Math.max(39,q.y-33);body+='<rect x="'+(sx-42)+'" y="'+(sy-15)+'" width="84" height="30" rx="15" fill="#ef4444"/>'+svgText(sx,sy,'ابدأ',15,'#fff');body+='<rect x="'+(ex-42)+'" y="'+(ey-15)+'" width="84" height="30" rx="15" fill="#1c9f69"/>'+svgText(ex,ey,'نهاية',15,'#fff')}body+='<rect x="128" y="306" width="384" height="38" rx="18" fill="#ffffffee"/>'+svgText(320,326,(g.frames&&g.frames[i])||g.title,21,'#24413f');return'<svg class="frame-visual trace-frame" viewBox="0 0 640 360" role="img" aria-label="'+esc((g.frames&&g.frames[i])||g.title)+'" xmlns="http://www.w3.org/2000/svg">'+body+'</svg>'}
function svgForFrame(g,i){if((g.type==='dots'||g.type==='path')&&tracePoints(g).length>1)return traceSvg(g,i);var s=g.symbols||[g.icon],a=s[i%s.length]||g.icon,b=s[(i+1)%s.length]||g.icon,c=s[(i+2)%s.length]||g.icon,bg=['#e8faf7','#fff4cb','#eef4ff','#f7edff','#eaf8e5'][i%5],body='<rect width="640" height="360" rx="30" fill="'+bg+'"/><circle cx="78" cy="70" r="42" fill="#ffffffcc"/>'+svgText(78,70,String(i+1),30,'#0f8f8a')+'<circle cx="555" cy="280" r="62" fill="#ffffff88"/>';body+=svgText(150,168,a,76)+svgText(320,168,b,76)+svgText(490,168,c,76);if(i===1||i===3)body+='<path d="M210 168 H270 M370 168 H430" stroke="#0f8f8a" stroke-width="10" stroke-linecap="round"/><path d="M260 153 L280 168 L260 183 M420 153 L440 168 L420 183" fill="none" stroke="#0f8f8a" stroke-width="8"/>';body+=svgText(320,326,(g.frames&&g.frames[i])||g.title,22,'#24413f');return'<svg class="frame-visual" viewBox="0 0 640 360" role="img" aria-label="'+esc((g.frames&&g.frames[i])||g.title)+'" xmlns="http://www.w3.org/2000/svg">'+body+'</svg>'}
function renderLibrary(){stopReel();state.game=null;state.mode=null;state.round=null;var list=currentGames(),total=GAMES.length,h='<section class="hero compact-hero"><div><span class="hero-badge">'+total+' لعبة عملية</span><h2>اختر لعبة وابدأ مباشرة</h2><p>اللعبة تظهر أولًا، والشرح والطباعة والتصميم أسفلها عند الحاجة.</p></div><div class="hero-mini"><b>'+list.length+'</b><span>في '+levelLabel(state.level)+'</span></div></section><div class="level-tabs">';for(var i=1;i<=4;i++)h+='<button class="chip '+(i===state.level?'active':'')+'" data-level="'+i+'"><b>'+levelLabel(i)+'</b><small>'+levelAge(i)+'</small></button>';h+='</div><div class="library-head"><div><h2>'+levelLabel(state.level)+'</h2><p>'+levelHelp(state.level)+'</p></div><b>'+list.length+' ألعاب</b></div><div class="games-grid">';list.forEach(function(g){h+='<button class="game-card" data-game="'+g.id+'"><div class="game-art type-art">'+uiIcon(typeIconName(g.type),g.topic)+'</div><div class="game-body"><b>'+esc(g.title)+'</b><div class="meta"><span>'+esc(g.topic)+'</span><span>'+esc(g.id)+'</span></div><div class="play-now">ابدأ اللعبة الآن</div></div></button>'});h+='</div>';root.innerHTML=h;arr(root.querySelectorAll('[data-level]')).forEach(function(b){b.onclick=function(){state.level=Number(this.getAttribute('data-level'));db.prefs.level=state.level;saveStore();renderLibrary()}});arr(root.querySelectorAll('[data-game]')).forEach(function(b){b.onclick=function(){openGame(this.getAttribute('data-game'))}})}
function renderReel(g){var thumbs='',all='';for(var i=0;i<5;i++){thumbs+='<button class="step-thumb '+(i===0?'on':'')+'" data-step="'+i+'"><span>'+(i+1)+'</span><b>'+esc(g.frames[i])+'</b></button>';all+='<article class="overview-step" data-overview-step="'+i+'">'+svgForFrame(g,i)+'<b>'+(i+1)+' · '+esc(g.frames[i])+'</b></article>'}return'<section class="reel lesson-reel" id="reel"><div class="reel-head"><div><strong>شرح اللعبة بالصور</strong><small id="reelLabel">الخطوات الخمس</small></div><button id="reelAll" class="reel-all">عرض خطوة واحدة</button></div><div id="reelStage" class="reel-stage is-overview"><div id="reelSingle" class="reel-single" hidden>'+svgForFrame(g,0)+'<div id="frameCaption" class="frame-caption">'+esc(g.frames[0])+'</div></div><div id="reelOverview" class="reel-overview">'+all+'</div></div><div class="reel-controls"><button id="reelPrev" class="nav-main">السابق</button><button id="reelPlay">تشغيل الشرح</button><button id="reelNext" class="nav-main">التالي</button><button id="reelReplay">من البداية</button></div><div id="stepThumbs" class="step-thumbs">'+thumbs+'</div></section>'}
function compactReel(){var w=0;try{w=document.documentElement&&document.documentElement.clientWidth||window.innerWidth||0}catch(e){}return w>0&&w<=720}
function setupReel(){state.reelFrame=0;state.reelPlaying=false;state.reelOverview=false;var g=state.game;if(!g)return;function mark(){arr(root.querySelectorAll('[data-step]')).forEach(function(b,k){b.className='step-thumb '+(!state.reelOverview&&k===state.reelFrame?'on':'')})}function show(n){state.reelOverview=false;state.reelFrame=clamp(n,0,4);var single=el('reelSingle'),overview=el('reelOverview'),stage=el('reelStage');if(overview)overview.hidden=true;if(stage)stage.className='reel-stage is-single';if(single){single.hidden=false;single.innerHTML=svgForFrame(g,state.reelFrame)+'<div id="frameCaption" class="frame-caption">'+esc(g.frames[state.reelFrame])+'</div>'}var label=el('reelLabel'),all=el('reelAll');if(label)label.textContent='الخطوة '+(state.reelFrame+1)+' من 5';if(all)all.textContent='عرض كل الخطوات';mark()}function showOverview(){state.reelOverview=true;state.reelPlaying=false;clearTimeout(state.reelTimer);var single=el('reelSingle'),overview=el('reelOverview'),stage=el('reelStage'),label=el('reelLabel'),all=el('reelAll'),playBtn=el('reelPlay');if(single)single.hidden=true;if(overview)overview.hidden=false;if(stage)stage.className='reel-stage is-overview';if(label)label.textContent='كل الخطوات الخمس';if(all)all.textContent='عرض خطوة واحدة';if(playBtn)playBtn.textContent='تشغيل الشرح';mark()}function stop(){state.reelPlaying=false;clearTimeout(state.reelTimer);var b=el('reelPlay');if(b)b.textContent='تشغيل الشرح'}function schedule(){clearTimeout(state.reelTimer);if(!state.reelPlaying)return;state.reelTimer=setTimeout(function(){if(state.reelFrame<4){show(state.reelFrame+1);state.reelPlaying=true;var b=el('reelPlay');if(b)b.textContent='إيقاف';schedule()}else showOverview()},2300)}function play(){if(state.reelOverview||state.reelFrame>=4)show(0);state.reelPlaying=true;var b=el('reelPlay');if(b)b.textContent='إيقاف';schedule()}el('reelPrev').onclick=function(){stop();if(state.reelOverview)show(4);else show(state.reelFrame-1)};el('reelNext').onclick=function(){stop();if(state.reelOverview)show(0);else if(state.reelFrame>=4)showOverview();else show(state.reelFrame+1)};el('reelPlay').onclick=function(){if(state.reelPlaying)stop();else play()};el('reelReplay').onclick=function(){stop();show(0)};el('reelAll').onclick=function(){stop();if(state.reelOverview)show(state.reelFrame);else showOverview()};arr(root.querySelectorAll('[data-step]')).forEach(function(b){b.onclick=function(){stop();show(Number(this.getAttribute('data-step')))}});arr(root.querySelectorAll('[data-overview-step]')).forEach(function(b){b.onclick=function(){stop();show(Number(this.getAttribute('data-overview-step')))}});showOverview()}
