function scoreHudHtml(){return'<section class="score-hud"><div class="score-top"><div><small>نتيجة الجولة</small><strong id="roundState">جاهزون للبدء</strong></div><button id="hintBtn">'+uiIcon('hint','تلميح')+'</button></div><div class="score-counters"><span>المحاولات <b id="scoreAttempts">0</b></span><span>النجاحات <b id="scoreCorrect">0</b></span><span>التقدم <b id="scoreProgress">0%</b></span></div><div class="progress-track"><i id="scoreBar" style="width:0%"></i></div></section>'}
function renderScreenGame(g){stopReel();state.game=g;state.mode='screen';if(!state.session||state.session.task_id!==g.id)newSession(g,'screen');var prev=gameNeighbor(g,-1),next=gameNeighbor(g,1),h='<section class="game-view play-first-view"><nav class="game-switcher"><button id="backLibrary">'+uiIcon('games','كل الألعاب')+'</button><button id="prevGame">'+uiIcon('prev','اللعبة السابقة')+'</button><div class="game-count"><b>'+esc(g.id)+'</b><span>'+gamePosition(g)+'</span></div><button id="nextGame">'+uiIcon('next','اللعبة التالية')+'</button></nav>';h+='<section class="screen-game primary-game-panel"><div class="screen-game-head"><div class="game-heading">'+uiIcon(typeIconName(g.type),g.topic)+'<div><h2>'+esc(g.title)+'</h2><p>'+esc(g.topic)+' · '+esc(levelAge(g.level))+'</p></div></div><button class="btn" id="restartRound">'+uiIcon('restart','إعادة الجولة')+'</button></div>'+scoreHudHtml()+'<div id="challenge" class="challenge"></div><div class="game-tools"><button class="btn primary" id="finishScreen">'+uiIcon('finish','إنهاء الجولة')+'</button><button class="btn accent" id="printOne">'+uiIcon('print','طباعة ورقة اللعبة')+'</button><button class="btn" id="designerFromGame">'+uiIcon('draw','صمم ورقة لعب')+'</button></div><p class="score-note">هذه النتيجة تصف تفاعل الجولة فقط وليست تقييمًا لنمو الطفل.</p></section>';h+='<section class="after-play"><div class="section-title"><h3>بعد اللعب: الشرح والطباعة والتجربة الواقعية</h3><p>يمكنك تجاهل هذا الجزء أثناء اللعب والرجوع إليه عند الحاجة.</p></div>'+renderReel(g)+'<section class="paper-shortcuts"><div><h3>اللعب على الورق</h3><p>اطبع الورقة الجاهزة أو أنشئ ورقتك الخاصة بالرسم والأشكال والصور.</p></div><div class="action-row"><button class="btn accent" id="printOneBottom">'+uiIcon('print','طباعة الجاهزة')+'</button><button class="btn primary" id="designerBottom">'+uiIcon('draw','تصميم ورقة مخصصة')+'</button><button class="btn" id="offlineStart">'+uiIcon('paper','بطاقة اللعب الواقعي')+'</button></div></section><section class="materials compact-materials"><b>المواد المقترحة</b><div class="materials">'+g.materials.map(function(m){return'<span>'+esc(m)+'</span>'}).join('')+'</div></section>'+alternativesHtml(g)+'</section></section>';root.innerHTML=h;el('backLibrary').onclick=renderLibrary;el('prevGame').onclick=function(){openGame(prev.id)};el('nextGame').onclick=function(){openGame(next.id)};el('restartRound').onclick=function(){newSession(g,'screen');renderScreenGame(g)};el('finishScreen').onclick=function(){renderResult(g,'screen')};el('printOne').onclick=el('printOneBottom').onclick=function(){printGames([g])};el('designerFromGame').onclick=el('designerBottom').onclick=function(){openWorksheetDesigner(g)};el('offlineStart').onclick=function(){state.mode='offline';newSession(g,'offline');renderOfflineCard(g)};el('hintBtn').onclick=function(){state.round.hints++;toast((g.prompt||g.frames[0])+' — '+g.frames[1])};buildChallenge(g);enhanceLegacyVisuals(el('challenge'));updateScoreHud();setupReel();try{window.scrollTo(0,0)}catch(e){}}
function buildChallenge(g){var box=el('challenge');if(!box)return;if(g.type==='mark')buildMark(box,g);else if(g.type==='choice'||g.type==='pattern')buildChoice(box,g);else if(g.type==='match')buildMatch(box,g);else if(g.type==='sort')buildSort(box,g);else if(g.type==='memory')buildMemory(box,g);else if(g.type==='order')buildOrder(box,g);else if(g.type==='puzzle')buildPuzzle(box,g);else if(g.type==='dots'||g.type==='path')buildTrace(box,g);else if(g.type==='draw')buildDraw(box,g);else if(g.type==='create')buildCreate(box,g);else box.innerHTML='<p>هذه اللعبة تعمل أفضل على الورق.</p>';enhanceLegacyVisuals(box)}
function buildMark(box,g){var source=g.markOptions||[],opts=shuffle(source.map(function(x,i){return{v:x[0],ok:!!x[1],i:i}})),h='<div class="mark-board level-'+g.level+'"><h3>'+esc(g.prompt||'اختر كل العناصر المناسبة')+'</h3><p class="mark-help">انقر على الشكل أو الصورة نفسها للتفعيل أو إلغاء التفعيل. علامة ✓ الصغيرة أسفل البطاقة مجرد مؤشر.</p><div class="mark-grid">';for(var i=0;i<opts.length;i++)h+='<button class="mark-option" data-mark="'+i+'" data-correct="'+(opts[i].ok?'1':'0')+'" data-value="'+esc(opts[i].v)+'"><span class="mark-value">'+visualMarkup(opts[i].v)+'</span><span class="mark-box" aria-hidden="true"></span></button>';h+='</div><div class="action-row mark-actions"><button class="btn primary" id="checkMarks">'+uiIcon('check','تحقق من الاختيارات')+'</button><button class="btn" id="clearMarks">إلغاء العلامات الحالية</button></div><p id="challengeMsg" class="challenge-msg">اختر كل ما يطابق القاعدة؛ قد توجد عدة إجابات صحيحة.</p></div>';box.innerHTML=h;function hasClass(n,c){return(' '+n.className+' ').indexOf(' '+c+' ')>=0}arr(box.querySelectorAll('.mark-option')).forEach(function(b){b.onclick=function(){if(this.disabled||hasClass(this,'checked'))return;var mark=this.querySelector('.mark-box');if(hasClass(this,'selected')||hasClass(this,'wrong')){this.className='mark-option';if(mark)mark.textContent=''}else{this.className='mark-option selected';if(mark)mark.textContent='✓'}}});el('checkMarks').onclick=function(){var bs=arr(box.querySelectorAll('.mark-option')),found=0,total=state.round?state.round.target:0;for(var i=0;i<bs.length;i++){var b=bs[i],sel=hasClass(b,'selected'),ok=b.getAttribute('data-correct')==='1',mark=b.querySelector('.mark-box');if(b.getAttribute('data-scored')==='1'){found++;continue}if(sel&&ok){b.className='mark-option checked';b.disabled=true;b.setAttribute('data-scored','1');if(mark)mark.textContent='✓';found++;scoreAttempt(true)}else if(sel&&!ok){b.className='mark-option wrong';if(mark)mark.textContent='×';if(b.getAttribute('data-wrong-scored')!=='1'){b.setAttribute('data-wrong-scored','1');scoreAttempt(false,false)}}}if(found>=total){el('challengeMsg').textContent='أحسنت! تم تمييز كل الخيارات المطلوبة.'}else el('challengeMsg').textContent='وجدت '+found+' من '+total+' إجابات صحيحة. ابحث عن البقية.'};el('clearMarks').onclick=function(){arr(box.querySelectorAll('.mark-option')).forEach(function(b){if(b.disabled)return;b.className='mark-option';b.removeAttribute('data-wrong-scored');var m=b.querySelector('.mark-box');if(m)m.textContent=''});el('challengeMsg').textContent='تم إلغاء العلامات غير المثبتة.'}}
function buildChoice(box,g){var seq='';if(g.sequence&&g.sequence.length)seq='<div class="sequence-row">'+g.sequence.map(function(x){return'<span>'+esc(x)+'</span>'}).join('')+'<span class="missing">؟</span></div>';box.innerHTML='<div class="challenge-card">'+seq+'<h3>'+esc(g.prompt||'اختر الصورة المناسبة')+'</h3><div class="choice-grid">'+(g.options||g.symbols||[]).map(function(o,k){return'<button data-choice="'+k+'">'+esc(o)+'</button>'}).join('')+'</div><p id="challengeMsg" class="challenge-msg">المس اختيارًا واحدًا.</p></div>';arr(box.querySelectorAll('[data-choice]')).forEach(function(b){b.onclick=function(){if(state.round.finished)return;var k=Number(this.getAttribute('data-choice'));if(k===g.answer){this.className='correct';el('challengeMsg').textContent='اختيار صحيح ✓';scoreAttempt(true);arr(box.querySelectorAll('[data-choice]')).forEach(function(x){x.disabled=true})}else{this.className='wrong';el('challengeMsg').textContent='جرّب اختيارًا آخر.';scoreAttempt(false,false)}}})}
function buildMatch(box,g){var pairs=g.pairs||[],left=shuffle(pairs.map(function(p,i){return{v:p[0],i:i}})),right=shuffle(pairs.map(function(p,i){return{v:p[1],i:i}})),h='<div class="match-board"><div class="match-col"><b>ابدأ من هنا</b>';left.forEach(function(x){h+='<button class="match-btn" data-side="a" data-pair="'+x.i+'">'+esc(x.v)+'</button>'});h+='</div><div class="match-col"><b>ثم اختر الزوج</b>';right.forEach(function(x){h+='<button class="match-btn" data-side="b" data-pair="'+x.i+'">'+esc(x.v)+'</button>'});h+='</div></div><p id="challengeMsg" class="challenge-msg">اختر صورة من كل جهة.</p>';box.innerHTML=h;var selected=null;arr(box.querySelectorAll('.match-btn')).forEach(function(b){b.onclick=function(){if(this.disabled)return;if(!selected){selected=this;this.className+=' selected';return}if(selected.getAttribute('data-side')===this.getAttribute('data-side')){selected.className=selected.className.replace(' selected','');selected=this;this.className+=' selected';return}if(selected.getAttribute('data-pair')===this.getAttribute('data-pair')){selected.className='match-btn done';this.className='match-btn done';selected.disabled=true;this.disabled=true;el('challengeMsg').textContent='زوج صحيح ✓';selected=null;scoreAttempt(true)}else{selected.className=selected.className.replace(' selected','');el('challengeMsg').textContent='ليسا زوجًا واحدًا؛ جرّب مرة أخرى.';selected=null;scoreAttempt(false,false)}}})}
function buildSort(box,g){var selected=null,items=shuffle((g.items||[]).map(function(x,i){return{v:x[0],target:x[1],i:i}}));box.innerHTML='<div class="sort-board"><h3>اختر قطعة ثم اختر مكانها</h3><div class="sort-bins">'+(g.bins||[]).map(function(x,k){return'<button class="sort-bin" data-bin="'+k+'"><span>'+esc(x)+'</span></button>'}).join('')+'</div><div class="sort-items">'+items.map(function(x){return'<button class="sort-item" data-item="'+x.i+'" data-target="'+x.target+'">'+esc(x.v)+'</button>'}).join('')+'</div><p id="challengeMsg" class="challenge-msg">ابدأ بقطعة واحدة.</p></div>';arr(box.querySelectorAll('.sort-item')).forEach(function(b){b.onclick=function(){if(this.disabled)return;selected=this;arr(box.querySelectorAll('.sort-item')).forEach(function(x){x.className=x.className.replace(' selected','')});this.className+=' selected'}});arr(box.querySelectorAll('.sort-bin')).forEach(function(b){b.onclick=function(){if(!selected){el('challengeMsg').textContent='اختر قطعة أولًا.';return}if(selected.getAttribute('data-target')===this.getAttribute('data-bin')){selected.className='sort-item done';selected.disabled=true;el('challengeMsg').textContent='في المكان المناسب ✓';selected=null;scoreAttempt(true)}else{selected.className=selected.className.replace(' selected','');selected=null;el('challengeMsg').textContent='جرّب مكانًا آخر.';scoreAttempt(false,false)}}})}
function buildMemory(box,g){var cards=[];(g.cards||[]).forEach(function(x,i){cards.push({v:x,p:i});cards.push({v:x,p:i})});cards=shuffle(cards);box.innerHTML='<div class="memory-head"><h3>ابحث عن الأزواج</h3><button id="peekMemory" class="btn">👀 نظرة سريعة</button></div><div class="memory-grid">'+cards.map(function(x,k){return'<button class="memory-card hidden-card" data-card="'+k+'" data-pair="'+x.p+'" data-value="'+esc(x.v)+'">'+esc(x.v)+'</button>'}).join('')+'</div>';var open=[];function closeOpen(){open=[]}arr(box.querySelectorAll('.memory-card')).forEach(function(b){b.onclick=function(){if(this.disabled||open.indexOf(this)>=0||open.length===2)return;this.className='memory-card';open.push(this);if(open.length===2){var a=open[0],c=open[1];if(a.getAttribute('data-pair')===c.getAttribute('data-pair')){setTimeout(function(){a.className='memory-card done';c.className='memory-card done';a.disabled=true;c.disabled=true;closeOpen();scoreAttempt(true)},350)}else{scoreAttempt(false,false);setTimeout(function(){a.className='memory-card hidden-card';c.className='memory-card hidden-card';closeOpen()},650)}}}});el('peekMemory').onclick=function(){state.round.hints++;var cs=arr(box.querySelectorAll('.memory-card'));cs.forEach(function(c){if(!c.disabled)c.className='memory-card'});setTimeout(function(){cs.forEach(function(c){if(!c.disabled)c.className='memory-card hidden-card'})},850)}}
function buildOrder(box,g){var target=g.order||[],cards=shuffle(target.slice()),picked=[];box.innerHTML='<div class="order-zone"><h3>المس الصور بالترتيب</h3><div class="order-answer" id="orderAnswer"></div><div class="order-grid">'+cards.map(function(x,k){return'<button data-order="'+k+'" data-value="'+esc(x)+'">'+esc(x)+'</button>'}).join('')+'</div><p id="challengeMsg" class="challenge-msg">اختر الصورة الأولى.</p><button class="btn" id="resetOrder">↺ ابدأ الترتيب من جديد</button></div>';function reset(){picked=[];el('orderAnswer').innerHTML='';arr(box.querySelectorAll('[data-order]')).forEach(function(b){b.disabled=false;b.className=''});el('challengeMsg').textContent='اختر الصورة الأولى.'}arr(box.querySelectorAll('[data-order]')).forEach(function(b){b.onclick=function(){if(this.disabled)return;picked.push(this.getAttribute('data-value'));this.disabled=true;this.className='done';el('orderAnswer').innerHTML=picked.map(function(x){return'<span>'+esc(x)+'</span>'}).join('');if(picked.length===target.length){var ok=true;for(var i=0;i<target.length;i++)if(picked[i]!==target[i])ok=false;if(ok){el('challengeMsg').textContent='ترتيب صحيح ✓';scoreAttempt(true)}else{el('challengeMsg').textContent='هذا ترتيب مختلف؛ جرّب من جديد.';scoreAttempt(false,false);setTimeout(reset,750)}}}});el('resetOrder').onclick=reset}
function buildPuzzle(box,g){var syms=(g.symbols||[]).slice(0,4),pieces=shuffle(syms.map(function(v,i){return{v:v,i:i}})),slots=shuffle(syms.map(function(v,i){return{v:v,i:i}})),selected=null,h='<div class="puzzle-wrap"><h3>ضع كل قطعة فوق شكلها</h3><div class="puzzle-pieces">';pieces.forEach(function(x){h+='<button class="puzzle-piece" data-piece="'+x.i+'">'+esc(x.v)+'</button>'});h+='</div><div class="puzzle-slots">';slots.forEach(function(x){h+='<button class="puzzle-slot" data-slot="'+x.i+'"><span>'+esc(x.v)+'</span></button>'});h+='</div><p id="challengeMsg" class="challenge-msg">اختر قطعة ثم مكانها.</p></div>';box.innerHTML=h;arr(box.querySelectorAll('.puzzle-piece')).forEach(function(b){b.onclick=function(){if(this.disabled)return;selected=this;arr(box.querySelectorAll('.puzzle-piece')).forEach(function(x){x.className=x.className.replace(' selected','')});this.className+=' selected'}});arr(box.querySelectorAll('.puzzle-slot')).forEach(function(b){b.onclick=function(){if(!selected){el('challengeMsg').textContent='اختر قطعة أولًا.';return}if(selected.getAttribute('data-piece')===this.getAttribute('data-slot')){this.className='puzzle-slot filled';this.innerHTML=selected.innerHTML;this.disabled=true;selected.disabled=true;selected.className='puzzle-piece done';selected=null;el('challengeMsg').textContent='قطعة في مكانها ✓';scoreAttempt(true)}else{selected.className=selected.className.replace(' selected','');selected=null;el('challengeMsg').textContent='جرّب مكانًا آخر.';scoreAttempt(false,false)}}})}
function canvasPos(c,e){var r=c.getBoundingClientRect(),t=e.touches&&e.touches[0]?e.touches[0]:e;return{x:t.clientX-r.left,y:t.clientY-r.top}}
function setupCanvas(c,g,mode){var r=c.getBoundingClientRect(),d=window.devicePixelRatio||1;if(d>2)d=2;var cw=Math.max(320,Math.floor(r.width||320)),ch=Math.max(300,Math.floor(r.height||360));c.width=Math.floor(cw*d);c.height=Math.floor(ch*d);var ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);var w=cw,h=ch,points=tracePoints(g),nextIndex=1,down=false,started=false,last=null,hitRadius=Math.max(34,Math.min(48,w*.065));ctx.lineCap='round';ctx.lineJoin='round';function paintGuide(){ctx.clearRect(0,0,w,h);ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);for(var j=0;j<points.length-1;j++){var a=tracePoint(points[j],w,h),b=tracePoint(points[j+1],w,h);ctx.strokeStyle='#c6d7d5';ctx.lineWidth=6;if(ctx.setLineDash)ctx.setLineDash([12,10]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(ctx.setLineDash)ctx.setLineDash([])}for(var i=0;i<points.length;i++){var q=tracePoint(points[i],w,h);ctx.beginPath();ctx.arc(q.x,q.y,i===0||i===points.length-1?15:12,0,Math.PI*2);ctx.fillStyle=i===0?'#ef4444':(i===points.length-1?'#1c9f69':'#0f8f8a');ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 13px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(i+1),q.x,q.y)}if(points.length){var s=tracePoint(points[0],w,h),e=tracePoint(points[points.length-1],w,h);ctx.font='bold 15px Tahoma,Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#ef4444';ctx.fillText('ابدأ',s.x,Math.max(16,s.y-28));ctx.fillStyle='#1c9f69';ctx.fillText('نهاية',e.x,Math.max(16,e.y-28))}}function near(a,b,rad){var dx=a.x-b.x,dy=a.y-b.y;return Math.sqrt(dx*dx+dy*dy)<=rad}function markCheckpoint(index){var q=tracePoint(points[index],w,h);ctx.beginPath();ctx.arc(q.x,q.y,index===points.length-1?17:14,0,Math.PI*2);ctx.fillStyle='#1c9f69';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 13px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(index+1),q.x,q.y)}function check(p){if(nextIndex>=points.length)return;var q=tracePoint(points[nextIndex],w,h);if(near(p,q,hitRadius)){markCheckpoint(nextIndex);nextIndex++;scoreAttempt(true);if(nextIndex>=points.length){down=false;toast('أحسنت، وصلت إلى النهاية ✓')}}}function start(e){var p=canvasPos(c,e);if(!points.length)return;var first=tracePoint(points[0],w,h);if(!started){if(!near(p,first,hitRadius+12)){toast('ابدأ من الدائرة الحمراء رقم 1');if(e.preventDefault)e.preventDefault();return}started=true;last=first;down=true}else{down=true;last=p}if(e.preventDefault)e.preventDefault()}function move(e){if(!down||!started)return;var p=canvasPos(c,e);ctx.strokeStyle='#0f8f8a';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p;check(p);if(e.preventDefault)e.preventDefault()}function end(){down=false;last=null}paintGuide();c.addEventListener('mousedown',start);c.addEventListener('mousemove',move);document.addEventListener('mouseup',end);c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',end)}
function buildTrace(box,g){box.innerHTML='<div class="trace-wrap"><h3>'+(g.type==='dots'?'صل النقاط بالترتيب':'اتبع الطريق حتى النهاية')+'</h3><div class="trace-legend"><span class="trace-start"><i></i>ابدأ من الأحمر رقم 1</span><span class="trace-end"><i></i>انتهِ عند الأخضر</span></div><canvas id="playCanvas" class="play-canvas"></canvas><p class="challenge-msg">ابدأ من الدائرة الحمراء رقم 1، ثم اتبع نفس الخط والنقاط بالترتيب حتى الدائرة الخضراء الأخيرة. شكل المسار هنا مطابق تمامًا لشاشة الشرح والورقة المطبوعة.</p><button class="btn" id="clearTrace">↺ إعادة المسار</button></div>';setTimeout(function(){setupCanvas(el('playCanvas'),g,g.type)},20);el('clearTrace').onclick=function(){newSession(g,'screen');renderScreenGame(g)}}
function buildDraw(box,g){box.innerHTML='<div class="trace-wrap"><h3>أكمل نصف الشكل بطريقتك</h3><canvas id="playCanvas" class="play-canvas"></canvas><div class="action-row"><button class="btn primary" id="doneDraw">✓ أنجزت المحاولة</button><button class="btn" id="clearDrawGame">↺ مسح وإعادة</button></div><p class="challenge-msg">هذه لعبة رسم مفتوحة؛ لا يحكم التطبيق على جودة الرسم.</p></div>';setTimeout(function(){var c=el('playCanvas'),r=c.getBoundingClientRect(),d=window.devicePixelRatio||1;if(d>2)d=2;c.width=Math.max(320,Math.floor(r.width*d));c.height=Math.max(260,Math.floor(r.height*d));var ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);ctx.strokeStyle='#b7cbc9';ctx.lineWidth=5;if(ctx.setLineDash)ctx.setLineDash([10,8]);ctx.beginPath();ctx.arc(r.width/2,r.height/2,Math.min(r.width,r.height)*.28,-Math.PI/2,Math.PI/2);ctx.stroke();if(ctx.setLineDash)ctx.setLineDash([]);var down=false,last=null;function st(e){down=true;last=canvasPos(c,e);if(e.preventDefault)e.preventDefault()}function mv(e){if(!down)return;var p=canvasPos(c,e);ctx.strokeStyle='#0f8f8a';ctx.lineWidth=8;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p;if(e.preventDefault)e.preventDefault()}function en(){down=false}c.addEventListener('mousedown',st);c.addEventListener('mousemove',mv);document.addEventListener('mouseup',en);c.addEventListener('touchstart',st,{passive:false});c.addEventListener('touchmove',mv,{passive:false});c.addEventListener('touchend',en)},20);el('doneDraw').onclick=scoreManualComplete;el('clearDrawGame').onclick=function(){newSession(g,'screen');renderScreenGame(g)}}
function buildCreate(box,g){var chosen=[],hidden=-1;box.innerHTML='<div class="creator"><h3>اصنع لغزًا للمرافق</h3><p>اختر 3 رموز، ثم أخفِ واحدًا واسأل: ما الرمز الناقص؟</p><div class="creator-source">'+(g.symbols||[]).map(function(x,k){return'<button data-symbol="'+k+'">'+esc(x)+'</button>'}).join('')+'</div><div id="creatorLine" class="creator-line"><span>؟</span><span>؟</span><span>؟</span></div><div class="action-row"><button class="btn" id="hideCreator" disabled>🙈 أخفِ رمزًا</button><button class="btn primary" id="solveCreator" disabled>✓ المرافق حل اللغز</button></div><p id="challengeMsg" class="challenge-msg">ابدأ باختيار ثلاثة رموز.</p></div>';function paint(){var h='';for(var i=0;i<3;i++)h+='<span>'+(i<chosen.length?(i===hidden?'؟':esc(chosen[i])):'؟')+'</span>';el('creatorLine').innerHTML=h;el('hideCreator').disabled=chosen.length<3;el('solveCreator').disabled=hidden<0}arr(box.querySelectorAll('[data-symbol]')).forEach(function(b){b.onclick=function(){if(chosen.length>=3)return;chosen.push((g.symbols||[])[Number(this.getAttribute('data-symbol'))]);paint();if(chosen.length===3)el('challengeMsg').textContent='الآن أخفِ رمزًا واحدًا.'}});el('hideCreator').onclick=function(){if(chosen.length<3)return;hidden=Math.floor(Math.random()*3);paint();el('challengeMsg').textContent='اسأل المرافق: ما الرمز الناقص؟'};el('solveCreator').onclick=function(){scoreManualComplete();el('challengeMsg').textContent='تم تبادل الدور وحل اللغز ✓';this.disabled=true};paint()}
function renderOfflineCard(g){stopReel();root.innerHTML='<section class="game-view"><div class="backline"><button id="backGame">← تفاصيل اللعبة</button><span>🧻 اللعب بدون الشاشة</span></div><section class="game-title-card"><h2>'+esc(g.icon+' '+g.title)+'</h2><p>جهّز المواد، ثم اترك الجهاز جانبًا. التطبيق لا يراقب ما يحدث بعد ذلك.</p><div class="materials">'+g.materials.map(function(m){return'<span>✓ '+esc(m)+'</span>'}).join('')+'</div></section><section class="offline-card"><h2>الخطوات المختصرة</h2><ol>'+g.frames.map(function(x){return'<li>'+esc(x)+'</li>'}).join('')+'</ol><div class="action-row"><button class="btn accent" id="printCard">🖨 اطبع الورقة</button><button class="btn primary" id="finishOffline">✓ انتهينا من البطاقة</button></div><p><strong>مهم:</strong> لا يلزم الرجوع للتطبيق بعد اللعب ولا تقديم صورة أو إثبات.</p></section></section>';el('backGame').onclick=function(){openGame(g.id)};el('printCard').onclick=function(){printGames([g])};el('finishOffline').onclick=function(){renderResult(g,'offline')}}
function renderResult(g,mode){stopReel();if(!state.session)newSession(g,mode);state.session.artifact.selected_mode=mode;var r=state.round||{attempts:0,correct:0,wrong:0,completed:0,target:0,hints:0},pct=mode==='screen'?completionPct():null,acc=mode==='screen'?accuracy():null,h='<section class="result-card"><div class="result-icon">🏁</div><h2>نتيجة الجولة</h2><p>'+(mode==='screen'?esc(resultText()):'انتهت بطاقة اللعب الواقعي. لم يراقب التطبيق التنفيذ خارج الشاشة.')+'</p>';if(mode==='screen')h+='<div class="result-numbers"><span><b>'+r.attempts+'</b>محاولات</span><span><b>'+r.correct+'</b>نجاحات</span><span><b>'+pct+'%</b>تقدم الفكرة</span><span><b>'+acc+'%</b>دقة المحاولات</span></div>';h+='<section class="result-assist"><h3>كيف كانت المساعدة؟</h3><div class="assist-row"><button data-assist="محاولة ذاتية">محاولة ذاتية</button><button data-assist="تلميح بسيط">تلميح بسيط</button><button data-assist="مع المرافق" class="active">مع المرافق</button></div><label for="reflectionText">ملاحظة اختيارية</label><textarea id="reflectionText" placeholder="مثال: أحب اللعبة عندما استخدمنا قطعًا حقيقية."></textarea></section><div class="action-row result-actions"><button class="btn primary" id="saveResult">💾 حفظ النتيجة محليًا</button><button class="btn" id="retryResult">↺ إعادة نفس اللعبة</button><button class="btn accent" id="libraryResult">🎲 اختيار لعبة أخرى</button></div><p class="score-note">لا يبدأ التطبيق لعبة أخرى تلقائيًا؛ أنت من يختار ما بعد هذه الشاشة.</p></section>';root.innerHTML=h;state.assist='مع المرافق';arr(root.querySelectorAll('[data-assist]')).forEach(function(b){b.onclick=function(){state.assist=this.getAttribute('data-assist');arr(root.querySelectorAll('[data-assist]')).forEach(function(x){x.className=''});this.className='active'}});el('saveResult').onclick=function(){state.session.reflection=el('reflectionText').value||'';state.session.assistance_level=state.assist;state.session.finished_at=new Date().toISOString();state.session.artifact.result={mode:mode,attempts:r.attempts,correct:r.correct,wrong:r.wrong,completed:r.completed,target:r.target,progress_percent:pct,accuracy_percent:acc,hints:r.hints,status:mode==='screen'?resultText():'انتهت البطاقة خارج الشاشة'};db.sessions.unshift(state.session);if(db.sessions.length>100)db.sessions.length=100;saveStore();this.disabled=true;toast(storage?'تم حفظ نتيجة الجولة على هذا الجهاز':'لم يتوفر حفظ دائم؛ استخدم التصدير من السجل')};el('retryResult').onclick=function(){newSession(g,mode);if(mode==='screen')renderScreenGame(g);else renderOfflineCard(g)};el('libraryResult').onclick=renderLibrary}
function markWorksheetSVG(g){var opts=g.markOptions||[],cols=4,cardW=220,cardH=205,startX=95,startY=330,gapX=15,gapY=18,body='<rect width="1120" height="1584" fill="white"/><rect x="45" y="45" width="1030" height="1494" rx="34" fill="#fbfefd" stroke="#0f8f8a" stroke-width="5"/>'+svgText(560,105,'تمييز واختيار بعلامة صح',34,'#0f8f8a')+svgText(560,168,g.title,42,'#17302f')+svgText(560,225,g.prompt||'ضع علامة صح على الاختيارات المطلوبة',27,'#24413f')+svgText(560,275,'انظر إلى الصورة أولًا، ثم ضع ✓ داخل المربع الصغير',23,'#647b79');for(var i=0;i<opts.length;i++){var row=Math.floor(i/cols),col=i%cols,x=startX+col*(cardW+gapX),y=startY+row*(cardH+gapY),value=String(opts[i][0]);body+='<rect x="'+x+'" y="'+y+'" width="'+cardW+'" height="'+cardH+'" rx="22" fill="#fff" stroke="#d5e8e5" stroke-width="4"/>';body+='<rect x="'+(x+cardW-38)+'" y="'+(y+12)+'" width="24" height="24" rx="4" fill="#fff" stroke="#789995" stroke-width="3"/>';body+=svgText(x+cardW/2,y+cardH/2+10,value,value.length>5?31:46,'#17302f')}var rows=Math.ceil(opts.length/cols),noteY=Math.min(1460,startY+rows*(cardH+gapY)+35);body+=svgText(560,noteY,'المربع صغير حتى يبقى التركيز على الصورة أو الشيء نفسه',22,'#647b79');return'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1120 1584">'+body+'</svg>'}
function worksheetSVG(g){if(g.type==='mark')return markWorksheetSVG(g);var body='<rect width="1120" height="1584" fill="white"/><rect x="45" y="45" width="1030" height="1494" rx="34" fill="#fbfefd" stroke="#0f8f8a" stroke-width="5"/>'+svgText(560,100,'ألعاب إبداعية عبر الشاشة — أو بدون الشاشة',30,'#0f8f8a')+svgText(560,165,g.title,44,'#17302f')+svgText(560,215,levelLabel(g.level)+' · '+levelAge(g.level),24,'#45605e');body+='<g transform="translate(80 270) scale(1.5)">'+svgForFrame(g,2).replace('<svg class="frame-visual"','<svg width="640" height="360"')+'</g>';body+=svgText(560,900,'نفّذ الفكرة على الورق أو بأشياء حقيقية',32,'#17302f');var y=970;g.frames.forEach(function(x,k){body+=svgText(560,y+k*70,(k+1)+' · '+x,28,'#24413f')});body+='<line x1="100" y1="1360" x2="1020" y2="1360" stroke="#8da9a6" stroke-width="3" stroke-dasharray="14 10"/>'+svgText(560,1415,'مساحة رسم أو إضافة لغز من الطفل والمرافق',26,'#45605e')+'<rect x="120" y="1450" width="880" height="55" rx="14" fill="none" stroke="#b7cbc9" stroke-width="3" stroke-dasharray="10 8"/>';return'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1120 1584">'+body+'</svg>'}
function printGames(list){var p=el('printArea');p.innerHTML=list.map(function(g){return'<article class="print-sheet"><h1>'+esc(g.title)+'</h1>'+worksheetSVG(g)+'<p>اللعب الحقيقي أولًا · لا توجد مطالبة بإثبات الإنجاز.</p></article>'}).join('');setTimeout(function(){window.print()},100)}
function downloadBlob(name,type,text){try{var blob=new Blob([text],{type:type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(u);if(a.parentNode)a.parentNode.removeChild(a)},200)}catch(e){toast('تعذر التنزيل على هذا المتصفح؛ استخدم الطباعة بدلًا منه.')}}
function downloadWorksheet(g){downloadBlob('app360-'+g.id+'-worksheet.svg','image/svg+xml;charset=utf-8',worksheetSVG(g))}
function openWorksheets(){var h='<p>كل لعبة لها ورقة مستقلة. اطبع لعبة واحدة أو الحزمة كاملة.</p><div class="action-row"><button class="btn accent" id="printAll">🖨 طباعة كل الأوراق</button><button class="btn" id="downloadPack">⬇ تنزيل حزمة HTML</button></div><div class="worksheet-list">';GAMES.forEach(function(g){h+='<div class="worksheet-row"><div class="wi">'+esc(g.icon)+'</div><div><b>'+esc(g.id+' · '+g.title)+'</b><small>'+esc(levelAge(g.level))+' · '+esc(g.topic)+'</small></div><div class="wa"><button class="btn" data-print="'+g.id+'">طباعة</button><button class="btn" data-down="'+g.id+'">SVG</button></div></div>'});h+='</div>';openSheet('🖨 أوراق العمل',h);el('printAll').onclick=function(){printGames(GAMES)};el('downloadPack').onclick=function(){var sheets=GAMES.map(function(g){return'<article style="page-break-after:always;direction:rtl;font-family:Arial"><h1>'+esc(g.title)+'</h1>'+worksheetSVG(g)+'</article>'}).join('');downloadBlob('app360-screen-to-move-'+GAMES.length+'-worksheets.html','text/html;charset=utf-8','<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>'+GAMES.length+' ورقة لعب</title><body>'+sheets+'</body></html>')};arr(el('sheetBody').querySelectorAll('[data-print]')).forEach(function(b){b.onclick=function(){printGames([findGame(this.getAttribute('data-print'))])}});arr(el('sheetBody').querySelectorAll('[data-down]')).forEach(function(b){b.onclick=function(){downloadWorksheet(findGame(this.getAttribute('data-down')))}})}
function openHistory(){var list=db.sessions||[],h='<div class="action-row"><button class="btn" id="exportHistory">تصدير JSON</button><button class="btn danger" id="deleteHistory">حذف السجل المحلي</button></div><p>النتائج تخص جولات اللعب داخل التطبيق، وليست تقييمًا نمائيًا.</p>';if(!list.length)h+='<p>لا توجد نتائج محفوظة.</p>';else list.forEach(function(s){var rr=s.artifact&&s.artifact.result||{},prog=rr.progress_percent==null?'—':rr.progress_percent+'%';h+='<div class="history-item"><b>'+esc((s.artifact&&s.artifact.title)||s.task_id)+'</b><div>'+esc(s.assistance_level||'')+' · '+esc(rr.mode==='offline'?'خارج الشاشة':'على الشاشة')+' · تقدم '+esc(prog)+'</div><small>'+esc(s.reflection||rr.status||'بدون ملاحظة')+'</small></div>'});openSheet('📚 نتائج اللعب المحلية',h);el('exportHistory').onclick=function(){downloadBlob('app360-a1-screen-move-history.json','application/json;charset=utf-8',JSON.stringify(db,null,2))};el('deleteHistory').onclick=function(){if(window.confirm('حذف كل النتائج المحفوظة على هذا الجهاز؟')){db.sessions=[];saveStore();hideSheet();setTimeout(openHistory,20)}}}

