function openWorksheetDesigner(game){var o=el('drawingOverlay');if(!o)return;var stamps=[['apple.svg','تفاحة',OBJECT_ASSET_BASE+'apple.svg'],['banana.svg','موز',OBJECT_ASSET_BASE+'banana.svg'],['ball.svg','كرة',OBJECT_ASSET_BASE+'ball.svg'],['book.svg','كتاب',OBJECT_ASSET_BASE+'book.svg'],['car.svg','سيارة',OBJECT_ASSET_BASE+'car.svg'],['cat.svg','قطة',OBJECT_ASSET_BASE+'cat.svg'],['chair.svg','كرسي',OBJECT_ASSET_BASE+'chair.svg'],['cup.svg','كوب',OBJECT_ASSET_BASE+'cup.svg'],['shoe.svg','حذاء',OBJECT_ASSET_BASE+'shoe.svg'],['spoon.svg','ملعقة',OBJECT_ASSET_BASE+'spoon.svg'],['toothbrush.svg','فرشاة',OBJECT_ASSET_BASE+'toothbrush.svg'],['water.svg','ماء',OBJECT_ASSET_BASE+'water.svg'],['elephant.jpg','فيل',WORD_IMAGE_BASE+'corrected-elephant-v24.jpg'],['lion.jpg','أسد',WORD_IMAGE_BASE+'corrected-lion-v24.jpg'],['turtle.jpg','سلحفاة',WORD_IMAGE_BASE+'corrected-turtle-v24.jpg']],stampHtml='';for(var i=0;i<stamps.length;i++)stampHtml+='<button class="stamp-btn" data-stamp="'+stamps[i][2]+'" title="'+esc(stamps[i][1])+'"><img src="'+stamps[i][2]+'" alt="'+esc(stamps[i][1])+'"><small>'+esc(stamps[i][1])+'</small></button>';o.innerHTML='<button class="drawing-backdrop" data-close-drawing aria-label="إغلاق"></button><section class="drawing-panel worksheet-panel" role="dialog" aria-modal="true"><div class="drawing-head"><div><h2>تصميم ورقة لعب مخصصة</h2><small>A4 — نفس نسبة ورقة الطباعة</small></div><button class="close" data-close-drawing aria-label="إغلاق">×</button></div><div class="designer-layout"><aside class="designer-tools"><div class="tool-row"><button data-dtool="pen">'+uiIcon('draw','قلم')+'</button><button data-dtool="line">'+uiIcon('line','خط')+'</button><button data-dtool="rect">'+uiIcon('square','مربع')+'</button><button data-dtool="circle">'+uiIcon('circle','دائرة')+'</button><button data-dtool="triangle">'+uiIcon('triangle','مثلث')+'</button><button data-dtool="star">'+uiIcon('star','نجمة')+'</button><button data-dtool="eraser">'+uiIcon('eraser','ممحاة')+'</button></div><div class="color-row"><button data-dcolor="#1f2937">أسود</button><button data-dcolor="#ef4444">أحمر</button><button data-dcolor="#2563eb">أزرق</button><button data-dcolor="#16a34a">أخضر</button></div><label class="designer-text-label">نص على الورقة<input id="designerText" type="text" maxlength="40" placeholder="مثال: ضع دائرة حول القطة"></label><button data-dtool="text">'+uiIcon('text','إضافة النص بالنقر')+'</button><div class="stamp-title">صور وأشياء جاهزة</div><div class="stamp-grid">'+stampHtml+'</div><div class="designer-actions"><button id="designerUndo">'+uiIcon('undo','تراجع')+'</button><button id="designerClear">'+uiIcon('restart','مسح الورقة')+'</button>'+(game?'<button id="designerTemplate">'+uiIcon('paper','قالب اللعبة الحالية')+'</button>':'')+'<button id="designerPrint" class="btn accent">'+uiIcon('print','طباعة الورقة')+'</button><button id="designerSave" class="btn primary">'+uiIcon('save','حفظ صورة')+'</button></div></aside><div class="designer-paper-wrap"><div class="designer-paper"><canvas id="sharedCanvas"></canvas></div><p>اختر أداة ثم ارسم أو انقر داخل الورقة. الصور المأخوذة من مكتبة «اسمع وأشر وسمِّ» تعمل بدل الرموز التي قد لا تظهر على الأجهزة القديمة.</p></div></div></section>';o.hidden=false;o.setAttribute('aria-hidden','false');overlayKind='drawing';try{history.pushState({a1Overlay:'drawing'},'',location.href)}catch(e){}arr(o.querySelectorAll('[data-close-drawing]')).forEach(function(b){b.onclick=closeDrawing});setTimeout(function(){initWorksheetDesigner(game)},30)}
function initWorksheetDesigner(game){var c=el('sharedCanvas'),paper=c&&c.parentNode;if(!c||!paper)return;var width=Math.max(300,Math.min(794,paper.clientWidth||620)),height=Math.round(width*1.4142);c.width=width;c.height=height;c.style.width=width+'px';c.style.height=height+'px';var ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);draw.ctx=ctx;draw.tool='pen';draw.color='#1f2937';draw.history=[];draw.stamp=null;draw.start=null;draw.down=false;function pos(e){var r=c.getBoundingClientRect(),t=e.touches&&e.touches[0]?e.touches[0]:(e.changedTouches&&e.changedTouches[0]?e.changedTouches[0]:e);return{x:(t.clientX-r.left)*c.width/r.width,y:(t.clientY-r.top)*c.height/r.height}}function snap(){try{if(draw.history.length>=6)draw.history.shift();draw.history.push(c.toDataURL('image/png'))}catch(e){}}function restore(src){var im=new Image();im.onload=function(){ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height)};im.src=src}function setTool(t){draw.tool=t;draw.stamp=null;arr(document.querySelectorAll('[data-dtool]')).forEach(function(b){b.className=b.getAttribute('data-dtool')===t?'active':''})}function drawShape(tool,a,b){ctx.strokeStyle=draw.color;ctx.fillStyle=draw.color;ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';var x=Math.min(a.x,b.x),y=Math.min(a.y,b.y),w=Math.abs(b.x-a.x),h=Math.abs(b.y-a.y);ctx.beginPath();if(tool==='line'){ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y)}else if(tool==='rect'){ctx.rect(x,y,w,h)}else if(tool==='circle'){if(ctx.ellipse)ctx.ellipse((a.x+b.x)/2,(a.y+b.y)/2,w/2,h/2,0,0,Math.PI*2);else ctx.arc((a.x+b.x)/2,(a.y+b.y)/2,Math.max(w,h)/2,0,Math.PI*2)}else if(tool==='triangle'){ctx.moveTo((a.x+b.x)/2,y);ctx.lineTo(x,y+h);ctx.lineTo(x+w,y+h);ctx.closePath()}ctx.stroke()}function star(p){var r=32,r2=14;ctx.beginPath();for(var i=0;i<10;i++){var rr=i%2?r2:r,ang=-Math.PI/2+i*Math.PI/5,x=p.x+Math.cos(ang)*rr,y=p.y+Math.sin(ang)*rr;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();ctx.strokeStyle=draw.color;ctx.lineWidth=4;ctx.stroke()}function placeStamp(p){if(!draw.stamp)return;var im=new Image();im.onload=function(){snap();var size=Math.min(150,c.width*.22);ctx.drawImage(im,p.x-size/2,p.y-size/2,size,size)};im.src=draw.stamp}function addText(p){var inp=el('designerText'),txt=inp&&inp.value?inp.value:'اكتب هنا';snap();ctx.fillStyle=draw.color;ctx.font='bold 24px Tahoma, Arial';ctx.textAlign='center';ctx.fillText(txt,p.x,p.y)}function start(e){var p=pos(e);if(draw.tool==='stamp'){placeStamp(p);if(e.preventDefault)e.preventDefault();return}if(draw.tool==='star'){snap();star(p);if(e.preventDefault)e.preventDefault();return}if(draw.tool==='text'){addText(p);if(e.preventDefault)e.preventDefault();return}draw.down=true;draw.start=p;draw.last=p;snap();if(e.preventDefault)e.preventDefault()}function move(e){if(!draw.down||(draw.tool!=='pen'&&draw.tool!=='eraser'))return;var p=pos(e);ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=draw.tool==='eraser'?24:6;ctx.strokeStyle=draw.tool==='eraser'?'#fff':draw.color;ctx.beginPath();ctx.moveTo(draw.last.x,draw.last.y);ctx.lineTo(p.x,p.y);ctx.stroke();draw.last=p;if(e.preventDefault)e.preventDefault()}function end(e){if(!draw.down)return;var p=pos(e);if(draw.tool==='line'||draw.tool==='rect'||draw.tool==='circle'||draw.tool==='triangle')drawShape(draw.tool,draw.start,p);draw.down=false;draw.start=null;draw.last=null;if(e.preventDefault)e.preventDefault()}c.addEventListener('mousedown',start);c.addEventListener('mousemove',move);document.addEventListener('mouseup',end);c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',end,{passive:false});arr(document.querySelectorAll('[data-dtool]')).forEach(function(b){b.onclick=function(){setTool(this.getAttribute('data-dtool'))}});arr(document.querySelectorAll('[data-dcolor]')).forEach(function(b){b.onclick=function(){draw.color=this.getAttribute('data-dcolor')}});arr(document.querySelectorAll('[data-stamp]')).forEach(function(b){b.onclick=function(){draw.tool='stamp';draw.stamp=this.getAttribute('data-stamp');arr(document.querySelectorAll('[data-dtool]')).forEach(function(x){x.className=''})}});el('designerUndo').onclick=function(){if(draw.history.length)restore(draw.history.pop())};el('designerClear').onclick=function(){snap();ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height)};if(el('designerTemplate'))el('designerTemplate').onclick=function(){snap();drawWorksheetTemplate(ctx,c,game)};el('designerPrint').onclick=function(){var src=c.toDataURL('image/png'),p=el('printArea');p.innerHTML='<article class="print-sheet custom-designer-print"><img src="'+src+'" alt="ورقة اللعب المصممة"></article>';setTimeout(function(){window.print()},180)};el('designerSave').onclick=function(){try{var a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='app360-custom-worksheet.png';a.click()}catch(e){toast('تعذر حفظ الصورة على هذا المتصفح.')}};if(game)drawWorksheetTemplate(ctx,c,game);setTool('pen')}
function drawWorksheetTemplate(ctx,c,g){if(!g)return;ctx.save();ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#0f8f8a';ctx.lineWidth=3;ctx.strokeRect(18,18,c.width-36,c.height-36);ctx.fillStyle='#17302f';ctx.textAlign='center';ctx.font='bold 28px Tahoma, Arial';ctx.fillText(g.title,c.width/2,62);ctx.font='18px Tahoma, Arial';ctx.fillStyle='#45605e';ctx.fillText(g.prompt||g.topic,c.width/2,96);ctx.strokeStyle='#b7cbc9';if(ctx.setLineDash)ctx.setLineDash([8,8]);ctx.strokeRect(50,130,c.width-100,c.height-220);if(ctx.setLineDash)ctx.setLineDash([]);ctx.font='16px Tahoma, Arial';ctx.fillText('مساحة النشاط والرسم',c.width/2,c.height-55);if((g.type==='dots'||g.type==='path')&&tracePoints(g).length>1){var pts=tracePoints(g),w=c.width-140,h=(c.height-300),ox=70,oy=170;ctx.strokeStyle='#9abbb7';ctx.lineWidth=3;for(var i=0;i<pts.length-1;i++){var a=tracePoint(pts[i],w,h),b=tracePoint(pts[i+1],w,h);ctx.beginPath();ctx.moveTo(ox+a.x,oy+a.y);ctx.lineTo(ox+b.x,oy+b.y);ctx.stroke()}for(var j=0;j<pts.length;j++){var q=tracePoint(pts[j],w,h);ctx.beginPath();ctx.fillStyle=j===0?'#ef4444':(j===pts.length-1?'#1c9f69':'#0f8f8a');ctx.arc(ox+q.x,oy+q.y,10,0,Math.PI*2);ctx.fill()}}ctx.restore()}

function openProfile(){var h='<div class="profile-box"><p>يستخدم هذا التطبيق نفس اسم الطفل المحفوظ في «لوحة الطفل للرسم والكتابة المبكرة»، ونفس مكتبة التشجيع الصوتي؛ لا توجد نسخة ثانية من ملفات الأسماء.</p><label>اسم الطفل<input id="profileName" type="text" maxlength="40" value="'+esc(state.userName)+'"></label><label>النوع<select id="profileGender"><option value="girl" '+(state.userGender==='girl'?'selected':'')+'>طفلة</option><option value="boy" '+(state.userGender==='boy'?'selected':'')+'>طفل</option></select></label><div class="action-row"><button class="btn primary" id="saveProfile">حفظ الاسم</button><button class="btn" id="testAudioBtn">🔊 اختبار التشجيع</button></div><div id="audioStatus" class="audio-status">الصوت يستخدم الحزمة المشتركة الموجودة في تطبيق الرسم.</div></div>';openSheet('👤 الاسم والتشجيع الصوتي',h);el('saveProfile').onclick=function(){saveUser(el('profileName').value,el('profileGender').value)};el('testAudioBtn').onclick=testAudio}
