var draw={ctx:null,color:'#1f2937',eraser:false,down:false,last:null,history:[]};
function initDrawing(){var c=el('sharedCanvas'),wrap=c.parentNode,r=wrap.getBoundingClientRect(),d=window.devicePixelRatio||1;if(d>2)d=2;c.width=Math.max(320,Math.floor(r.width*d));c.height=Math.max(260,Math.floor(r.height*d));c.style.width=r.width+'px';c.style.height=r.height+'px';draw.ctx=c.getContext('2d');draw.ctx.setTransform(d,0,0,d,0,0);draw.ctx.fillStyle='#fff';draw.ctx.fillRect(0,0,r.width,r.height);draw.history=[];bindDrawing(c)}
function bindDrawing(c){if(c._bound)return;c._bound=true;function p(e){return canvasPos(c,e)}function snap(){try{if(draw.history.length>10)draw.history.shift();draw.history.push(c.toDataURL('image/png'))}catch(e){}}function start(e){draw.down=true;draw.last=p(e);snap();if(e.preventDefault)e.preventDefault()}function move(e){if(!draw.down||!draw.ctx)return;var q=p(e);draw.ctx.lineCap='round';draw.ctx.lineJoin='round';draw.ctx.lineWidth=draw.eraser?30:7;draw.ctx.strokeStyle=draw.eraser?'#fff':draw.color;draw.ctx.beginPath();draw.ctx.moveTo(draw.last.x,draw.last.y);draw.ctx.lineTo(q.x,q.y);draw.ctx.stroke();draw.last=q;if(e.preventDefault)e.preventDefault()}function end(){draw.down=false;draw.last=null}c.addEventListener('mousedown',start);c.addEventListener('mousemove',move);document.addEventListener('mouseup',end);c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',end)}
arr(document.querySelectorAll('[data-color]')).forEach(function(b){b.onclick=function(){draw.color=this.getAttribute('data-color');draw.eraser=false}});el('eraserBtn').onclick=function(){draw.eraser=true};el('clearDrawingBtn').onclick=function(){if(!draw.ctx)return;var c=el('sharedCanvas');draw.ctx.clearRect(0,0,c.width,c.height);draw.ctx.fillStyle='#fff';draw.ctx.fillRect(0,0,c.width,c.height)};el('undoBtn').onclick=function(){if(!draw.history.length||!draw.ctx)return;var img=new Image(),src=draw.history.pop(),c=el('sharedCanvas');img.onload=function(){draw.ctx.clearRect(0,0,c.width,c.height);draw.ctx.drawImage(img,0,0,c.clientWidth,c.clientHeight)};img.src=src};el('saveDrawingBtn').onclick=function(){try{var a=document.createElement('a');a.href=el('sharedCanvas').toDataURL('image/png');a.download='app360-shared-drawing.png';a.click()}catch(e){toast('تعذر حفظ الصورة على هذا المتصفح.')}};
